/// <summary>
///
/// </summary>
public void initValue()
{
    super();
    this.IsActive         = NoYes::Yes;
    this.ValidFrom        = systemDateGet();
    this.ValidTo          = dateMax();
    this.LegalEntity      = curExt();
    this.MSFRate          = 1.10;        // Default 1.10% MSF
    this.GSTRate          = 18.0;        // Default 18% GST
    this.IsIntraState     = NoYes::Yes;  // Default intra-state
    this.StateCode        = 'RJ';        // Default Rajasthan
    this.SysCreatedBy        = curUserId();
    this.SysCreatedDateTime  = DateTimeUtil::utcNow();
}

/// <summary>
///
/// </summary>
public void update()
{
    this.UserModifiedBy       = curUserId();
    this.UserModifiedDateTime = DateTimeUtil::utcNow();
    super();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret = super();

    if (!this.TerminalId)
        ret = checkFailed("Terminal ID is mandatory.");

    if (!this.BranchCode)
        ret = checkFailed("Branch Code is mandatory.");

    if (!this.POSReceivableAccount)
        ret = checkFailed("POS Receivable Account is mandatory.");

    if (this.MSFRate < 0 || this.MSFRate > 5)
        ret = checkFailed("MSF Rate must be between 0% and 5%.");

    // A window that ends before it starts silently hides the row: findByTerminalId
    // filters on ValidFrom <= today <= ValidTo, so the terminal reads as unmapped and
    // its settlements land in the manual queue with no obvious cause. Terminal
    // 41959954 was saved as 26-08-2026 to 30-04-2026 and did exactly that.
    if (this.ValidFrom && this.ValidTo && this.ValidTo < this.ValidFrom)
    {
        ret = checkFailed(strFmt(
            "Valid to (%1) is earlier than Valid from (%2). The terminal would never be found.",
            this.ValidTo, this.ValidFrom));
    }

    return ret;
}

/// <summary>
///
/// </summary>
public static boolean isIntraState(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map = PremPOSTerminalMap::findByTerminalId(_terminalId);
    return map.IsIntraState == NoYes::Yes;
}

/// <summary>
///
/// </summary>

public static PremPOSTerminalMap findByTerminalId(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map;

    select firstonly map
    where map.TerminalId == _terminalId
       && map.IsActive   == NoYes::Yes
       && map.ValidFrom  <= systemDateGet()
       && map.ValidTo    >= systemDateGet();

    return map;
}

/// <summary>
/// Bank account the acquirer credits this terminal's settlements into.
/// </summary>
public static BankAccountID getSettlementBankAccount(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map = PremPOSTerminalMap::findByTerminalId(_terminalId);
    return map.SettlementBankAccount;
}

/// <summary>
///
/// </summary>
public static LedgerDimensionAccount getReceivableAccount(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map = PremPOSTerminalMap::findByTerminalId(_terminalId);
    return map.POSReceivableAccount;
}
